text:
{
  "entries": [
    {
      "name_han": "进表科仪",
      "logic_thesis": "人与天沟通须依科仪进表：表文、坛场、步法、唱念合一，使下情得以上达、天恩得以下应。",
      "logic_chain": "1) 人间灾厄与祈求须有正式通道上达三界；2) 通道须借文书（表）与仪轨程式，非随意祷祝；3) 进表前须净坛、安神、请圣以立沟通场域；4) 表文须结构完整、名讳时辰无误，方具“契约”效力；5) 行持者依法跪奏、步罡、发符，表意随气上升；6) 得旨或感应后收坛谢圣，完成一次天人闭环。",
      "logic_practice": "1) 排四柱时先定“进表时机”：选日干支与用神、喜神同气相求之日时；2) 查命局中官印、天乙、驿马等是否能作“上达”之神；3) 若官印受克或空亡，先用神解救再论上达；4) 以年命与所选表日之天克地冲检验是否宜奏；5) 将表文主题映射为命局待解之病（如财破、官杀混、印弱），仪轨后复盘流年应期。",
      "logic_compare": "较《发表科仪》更强调“进”之程序与表文呈递；较《灵宝济炼科仪》偏重上达请命而非济幽炼度。与单纯符咒术比，进表科仪以文书—坛仪—天人契约为核心逻辑。"
    },
    {
      "name_han": "发表科仪",
      "logic_thesis": "发符、发表可将人意转化为可被神司接收的“公文”，关键在发得正、发得时、发得通。",
      "logic_chain": "1) 神明治理仿人间行政，须文书凭证；2) 发表即把祈愿格式化为神司可受理之件；3) 发前须敕符、净口、定意，以免表气驳杂；4) 按时辰方位发遣，与五行时空同频；5) 发后有验与否，取决于德行、坛规与命时是否相应；6) 收文、缴旨或化表，完成发—达—应流程。",
      "logic_practice": "1) 用日柱与时柱定“发”之动能（食伤为发、官印为达）；2) 表事属何类（病、讼、婚、迁）对应命局何神主事；3) 选发表日令与用神同气，避冲克命主日支；4) 看月令是否开通驿马、天乙等传递之神；5) 流年大运若官印受阻，宜先解局再发表，以免空发。",
      "logic_compare": "与《进表科仪》同属章奏体系，发表更重“发出、发遣”之动能；进表更重“呈进、跪奏”之礼序。相较民间乱发符咒，正统发表强调公文格式与时辰法度。"
    },
    {
      "name_han": "梅山教科仪",
      "logic_thesis": "梅山法以师传、罡步、兵将与地方神祇为骨干，重“教”之传承与“科”之可演练，以驱邪治病、护境安人为用。",
      "logic_chain": "1) 山野民间灾病多归因于邪祟、瘟煞、山精；2) 应对须有可传之“教”与可演之“科”，非散漫巫术；3) 师坛授法确立传承谱系与合法性；4) 兵将、符箓、锣鼓、罡步构成可操作技术链；5) 科仪依事分类（解结、和瘟、开光、安龙等）；6) 验于民生安稳，教法因有效而延续。",
      "logic_practice": "1) 命局见煞重、病符、羊刃冲激者，可对应“驱邪镇煞”类科事；2) 查年月是否逢七杀无制、伤官见官等“乱局”；3) 以印星为师传、比劫为兵将，看是否有“法众”可调；4) 选与命局用神五行相合之日做科；5) 大运转印或得贵人，宜加强传承与坛务，忌孤杀无依。",
      "logic_compare": "较正一、灵宝之经典科仪更偏地方性、武法与师教并重；较《瑶族度戒科仪》同属民间道教谱系，梅山重驱邪护境，度戒重成人礼与授箓身份。"
    },
    {
      "name_han": "瑶族度戒科仪",
      "logic_thesis": "度戒是身份转化仪式：经戒律、考验与授法，凡人进入可通神、可担责的宗教—社会新身份。",
      "logic_chain": "1) 社群秩序需明确谁可祭神、谁可执法；2) 身份不能自封，须经“度”之公开程序；3) 戒律约束行为，考验证明意志与承当；4) 授法、赐名、登籙使个人纳入神—人谱系；5) 度后享权利亦担义务（守戒、助仪、护族）；6) 仪式记忆强化族群认同与伦理。",
      "logic_practice": "1) 以日主强弱与印比看“承戒”之根气是否足；2) 官杀为戒律、印为师传，宜官印相生不宜官杀混杂；3) 选度戒年运宜印旺或官印相合，避冲破日支；4) 命带驿马、华盖者多与宗教身份、迁变仪轨相应；5) 度后流年见食伤泄秀，宜用于弘法服务而非破戒泄气。",
      "logic_compare": "与道教一般传度、授箓同构，但更嵌于瑶族成年礼与族群法；较《梅山教科仪》之反复行法事，度戒是一次性（或阶段性）身份跃迁，逻辑重心在“人”的转化而非“事”的解决。"
    },
    {
      "name_han": "灵宝济炼科仪",
      "logic_thesis": "生人积德、亡魂受炼：以灵宝法破狱、摄召、炼度、施食，使滞魄升迁，活人与幽冥同得济度。",
      "logic_chain": "1) 死非断灭，滞魂可因业障、横死、无祀而不得超；2) 滞则扰生，故济幽即安阳；3) 须破狱摄召方能使魂临坛受度；4) 水火交炼、符命赦罪转化其质；5) 施食、说法、往生咒补其资粮；6) 升度后回向斋主，完成阴阳两利。",
      "logic_practice": "1) 命见枭印夺食、官杀混战、或年命逢丧门吊客，可论“阴滞需济”；2) 用神取印与食伤并见者为“炼而能化”；3) 选水火既济之日时（如丙子、癸巳类）行济炼意象；4) 大运走死绝墓库而冲开者，注意祖荫、阴事、超度议题；5) 流年天克地冲命中长生帝旺，宜做功德回向而非硬抗。",
      "logic_compare": "较进表、发表之上达请命，济炼面向幽冥与炼魂；较一般超度经忏，灵宝济炼强调水火交炼与科仪结构完整，逻辑更偏“炼化”而非仅“超送”。"
    },
    {
      "name_han": "易筋经",
      "logic_thesis": "形正则气顺，筋强则膜坚：由外易筋、由内炼气，渐进改变体质与精神，达延年与武用双修。",
      "logic_chain": "1) 人衰先见于筋弛、膜弱、气滞；2) 被动药物不如主动改形；3) 按势导引拉伸筋膜，开通气血路径；4) 配合吐纳、意守使气贯筋膜；5) 日积月累，外壮内充；6) 形气神合一，方成“易”之实效。",
      "logic_practice": "1) 日主弱而筋骨象征之庚金、申酉受损者，宜补形炼筋；2) 选与用神同气之时辰练功（如用木则卯时导引）；3) 官杀过重如压力劳损，以印比护身、食伤疏导配合功法；4) 大运走金水运而体弱者，可主攻筋骨与呼吸；5) 忌在日破、空亡主时强练，宜养再炼。",
      "logic_compare": "较《赤凤髓》重导引吐纳谱系，《易筋经》更突出筋膜形变与武学外壮；较《寿世传真》之综合养生，易筋经方法更专一于“易筋”一条技术链。"
    },
    {
      "name_han": "赤凤髓",
      "logic_thesis": "仙道不离气法：图示导引、吐纳、胎息、存想，以简可学之术接通古典气论，使修炼有谱可依。",
      "logic_chain": "1) 气乱则病、气聚则康、气纯则近道；2) 古法散在诸书，学者难得系统图像；3) 以图定势、以诀定息、以想定神；4) 分病症与功用选相应导引；5) 由浅入深，从调息到胎息；6) 验于身安神清，而非玄谈。",
      "logic_practice": "1) 命局气弱（印比虚、日主无根）者优先吐纳补气；2) 火旺水枯者选清凉润下类导引意象；3) 木郁克土者配疏肝健运之势与时辰；4) 以流年干支五行选当令功法，勿逆令强行；5) 官印相生之年宜系统进阶，煞重之年宜守中调息。",
      "logic_compare": "与《易筋经》同属炼养，赤凤髓以图诀气法见长、覆盖面广；与《寿世传真》比，更偏“仙家气术汇编”，医学调护色彩较弱、图像谱系更强。"
    },
    {
      "name_han": "寿世传真",
      "logic_thesis": "寿由己造：清心寡欲、四时起居、导引按摩、药食有节，综合调摄可传真延命。",
      "logic_chain": "1) 夭寿不全由命定，行为与环境可改气血结局；2) 心为君主，欲火最耗精气；3) 起居顺四时阴阳是第一道防线；4) 导引按摩疏通已滞之经气；5) 药食辅助而非替代生活法度；6) 诸法一贯，真气可传、寿命可延。",
      "logic_practice": "1) 先断命局寿元相关：印比根气、日支宫位、神煞与天干通根；2) 用神为养命之主，起居食疗随用神五行；3) 忌神过旺之季加重养生权重（节欲、早睡、导引）；4) 大运入死绝则重调摄，入临官帝旺则重惜福勿纵；5) 流年食伤泄秀可练导引技艺，官杀主事则减负荷、增恢复。",
      "logic_compare": "较《肘后备急方》偏日常慢性调养而非急救；较《易筋经》《赤凤髓》更综合心性、起居、药食。逻辑是“寿世”的生活医学，而非单一功法或急方。"
    },
    {
      "name_han": "肘后备急方",
      "logic_thesis": "急病不待大医：备简易可寻之方，使卒急之际有药可施、有法可依，救人于俄顷。",
      "logic_chain": "1) 危急常在穷乡、旅途、深夜，名医难至；2) 故方须廉价、易得、可操作；3) 按病证分类罗列，便于检索；4) 先救急后缓图，止住恶化为第一义；5) 经验方经检验收录，重实效不炫奇；6) 人人可备，则群体抗风险能力上升。",
      "logic_practice": "1) 命局见伤官见官、羊刃驾杀、突发冲破者，应期宜预作“应急预案”；2) 用神为“常备解药”，忌神为“高危诱因”，生活中预避忌神之象；3) 流年驿马逢冲，出行携带对应五行护持与实际应急物；4) 日支受冲之月加强健康与安全检查；5) 印星为医药资源，印旺年宜完善知识与物资储备。",
      "logic_compare": "较《寿世传真》之长期养生，本书逻辑是“急备”；较道教科仪之祈禳，肘后以药物方技为主。同属葛洪一系济世精神，但路径是医学实用主义。"
    },
    {
      "name_han": "卜筮正宗",
      "logic_thesis": "六爻预测须守正法：以卦爻、六亲、用神、世应、动变与月日为纲，理法兼备方为正宗。",
      "logic_chain": "1) 占问须诚，一事一占，心乱则卦乱；2) 成卦后先定用神，不定用神则无的放矢；3) 六亲、世应、动变揭示关系与趋势；4) 月建日辰为六爻之“天时”，生克冲合定应期；5) 独发、两现、伏藏、进退神等细则修正断语；6) 理通法熟，验多则成正宗而非臆断。",
      "logic_practice": "1) 将求测事映射为命局用神（婚姻看财官、功名看官印等）与六爻用神对照；2) 以日柱为日辰、月令为月建，检验卦中用神旺衰；3) 大运流年作“后天月日”，看动爻应期是否落入运岁；4) 命卦与六爻同参：命定格局层次，爻断具体事应；5) 忌神发动之年少做重大决断，用神生旺之年可积极验证占断。",
      "logic_compare": "较纯象数玄谈，《卜筮正宗》强调可传授的断卦程式；较八字以出生盘论终身，六爻偏一事一占之动态决策。与科仪文本不同，其逻辑是预测方法论，而非祭祀沟通。"
    }
  ]
}
